#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn instrument_identity_catalog_is_complete_ordered_and_unique() {
        assert_eq!(VANILLA_INSTRUMENT_IDENTITIES.len(), 8);
        let mut resources = HashSet::new();
        for (index, (resource_id, instrument)) in VANILLA_INSTRUMENT_IDENTITIES.iter().enumerate() {
            assert_eq!(instrument.vanilla_registry_index(), index);
            assert!(resources.insert(*resource_id));
            assert!(resource_id.starts_with("minecraft:"));
        }
    }

    #[test]
    fn instrument_identity_catalog_preserves_vanilla_mappings() {
        assert_eq!(
            VanillaInstrumentIdentity::for_vanilla_registry_id(0),
            Some(VanillaInstrumentIdentity::PonderGoatHorn)
        );
        assert_eq!(
            VanillaInstrumentIdentity::for_vanilla_registry_id(7),
            Some(VanillaInstrumentIdentity::DreamGoatHorn)
        );
        assert_eq!(VanillaInstrumentIdentity::for_vanilla_registry_id(-1), None);
        assert_eq!(VanillaInstrumentIdentity::for_vanilla_registry_id(8), None);
        assert_eq!(
            VanillaInstrumentIdentity::for_resource_id("minecraft:call_goat_horn"),
            Some(VanillaInstrumentIdentity::CallGoatHorn)
        );
        assert_eq!(
            VanillaInstrumentIdentity::for_resource_id("example:custom_horn"),
            None
        );
        assert_eq!(
            VanillaInstrumentIdentity::DreamGoatHorn.resource_id(),
            "minecraft:dream_goat_horn"
        );
    }

    #[test]
    fn production_sources_do_not_redeclare_instrument_identity_facts() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/instruments.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                if source.contains("enum VanillaInstrumentIdentity")
                    || source.contains("const VANILLA_INSTRUMENT_KEYS")
                    || source.contains("fn vanilla_instrument_resource_id(")
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel instrument identity owners: {violations:?}"
        );
    }
}
